from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path

out = Path('/root/output/result.xlsx')
wb = load_workbook('/root/data/workbook.xlsx', data_only=False)
ws = wb['Task']

# Discovered layout:
# Task year headers: H10:L10 (2020-2024); series codes in Task column D.
# Data header row: row 4; series codes in Data column D; years in Data H:L.
# Data records: rows 21:38; full rectangular range A21:L38.
data_range = 'Data!$A$21:$L$38'
code_vector = 'Data!$D$21:$D$38'
year_vector = 'Data!$A$4:$L$4'

for start, end in [(12,17), (19,24), (26,31)]:
    for row in range(start, end + 1):
        for col in range(8, 13):
            col_letter = get_column_letter(col)
            ws.cell(row, col).value = f'=INDEX({data_range}, MATCH($D{row}, {code_vector}, 0), MATCH({col_letter}$10, {year_vector}, 0))'

for row in range(35, 41):
    offset = row - 35
    for col in range(8, 13):
        col_letter = get_column_letter(col)
        ws.cell(row, col).value = f'=({col_letter}{12+offset}-{col_letter}{19+offset})/{col_letter}{26+offset}*100'

stat_formulas = {
    42: 'MIN',
    43: 'MAX',
    44: 'MEDIAN',
    45: 'AVERAGE',
}
expected_labels = {
    42: 'Minimum',
    43: 'Maximum',
    44: 'Median',
    45: 'Simple mean',
    46: '25th percentile',
    47: '75th percentile',
}
for row, expected in expected_labels.items():
    actual = ws.cell(row, 5).value
    if actual != expected:
        raise ValueError(f'E{row} expected {expected!r}, found {actual!r}')
    for col in range(8, 13):
        col_letter = get_column_letter(col)
        if row in stat_formulas:
            ws.cell(row, col).value = f'={stat_formulas[row]}({col_letter}35:{col_letter}40)'
        elif row == 46:
            ws.cell(row, col).value = f'=PERCENTILE({col_letter}35:{col_letter}40, 0.25)'
        elif row == 47:
            ws.cell(row, col).value = f'=PERCENTILE({col_letter}35:{col_letter}40, 0.75)'

for col in range(8, 13):
    col_letter = get_column_letter(col)
    ws.cell(50, col).value = f'=SUMPRODUCT({col_letter}35:{col_letter}40,{col_letter}26:{col_letter}31)/SUM({col_letter}26:{col_letter}31)'

wb.save(out)
print('updated', out)
for addr in ['H12','H19','H26','H35','H42','H43','H44','H45','H46','H47','H50']:
    print(addr, ws[addr].value)
